import sys
MOD=998244353

def main():
    d = list(map(int, sys.stdin.buffer.read().split()))
    if not d:
        return
    n, m = d[0], d[1]
    first = [[n + 1] * n for _ in range(n)]
    p = 2
    for _ in range(m):
        l, r, x = d[p] - 1, d[p + 1] - 1, d[p + 2] - 1
        p += 3
        if r < first[x][l]:
            first[x][l] = r
    for row in first:
        z = n + 1
        for l in range(n - 1, -1, -1):
            if row[l] < z:
                z = row[l]
            row[l] = z
    comb = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        comb[i][0] = comb[i][i] = 1
        for j in range(1, i):
            comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % MOD
    dp = [[0] * n for _ in range(n)]
    for i in range(n):
        dp[i][i] = int(first[i][i] > i)
    for length in range(2, n + 1):
        for l in range(n - length + 1):
            r = l + length - 1
            total = 0
            for k in range(l, r + 1):
                if first[k][l] > r:
                    left = dp[l][k - 1] if k > l else 1
                    right = dp[k + 1][r] if k < r else 1
                    total += comb[length - 1][k - l] * left * right
            dp[l][r] = total % MOD
    print(dp[0][n - 1])

if __name__ == '__main__':
    main()

