import sys
MOD=998244353

def main():
    data=list(map(int,sys.stdin.buffer.read().split()))
    if not data:
        return
    n=data[0]
    a=data[1:]
    M=max(a)

    phi=list(range(M+1))
    for i in range(2,M+1):
        if phi[i] == i:
            for j in range(i,M+1,i):
                phi[j] -= phi[j] // i

    spf=list(range(M+1))
    for i in range(2, int(M**0.5)+1):
        if spf[i] == i:
            for j in range(i*i, M+1, i):
                if spf[j] == j:
                    spf[j] = i

    cache={}
    def get_divisors(x):
        z=x
        ds=[1]
        while z > 1:
            p=spf[z]
            e=0
            while z % p == 0:
                z //= p
                e += 1
            old=ds[:]
            q=1
            for _ in range(e):
                q *= p
                ds.extend(v*q for v in old)
        return tuple(ds)

    weighted=[0]*(M+1)
    answer=0
    power=1
    output=[]
    for x in a:
        ds=cache.get(x)
        if ds is None:
            ds=get_divisors(x)
            cache[x]=ds
        add=0
        for d in ds:
            add=(add + phi[d]*weighted[d]) % MOD
        answer=(2*answer + add) % MOD
        output.append(str(answer))
        for d in ds:
            weighted[d]=(weighted[d]+power) % MOD
        power=power*2 % MOD
    sys.stdout.write('\n'.join(output))

main()

