    if not a:
        return
    p = 0
    n, m, q = a[p], a[p+1], a[p+2]
    p += 3
    edges = []
    for _ in range(m):
        u, v, w = a[p]-1, a[p+1]-1, a[p+2]
        p += 3
        edges.append((u, v, w))
    closed = [False] * m

    def make_dist():
        d = [[INF] * n for _ in range(n)]
        for i in range(n):
            d[i][i] = 0
        for k, (u, v, w) in enumerate(edges):
            if not closed[k] and w < d[u][v]:
                d[u][v] = d[v][u] = w
        for k in range(n):
            dk = d[k]
            for i in range(n):
                di = d[i]
                x = di[k]
                if x == INF:
                    continue
                for j in range(n):
                    z = x + dk[j]
                    if z < di[j]:
                        di[j] = z
        return d

    dist = make_dist()
    ans = []
    for _ in range(q):
        typ = a[p]
        p += 1
        if typ == 1:
            e = a[p] - 1
            p += 1
            closed[e] = True
            dist = make_dist()
        else:
            x, y = a[p]-1, a[p+1]-1
            p += 2
            v = dist[x][y]
            ans.append(str(v if v < INF else -1))
    sys.stdout.write('\n'.join(ans))

