    if not data:
        return
    n, budget = data[0], data[1]
    machines = [tuple(data[2 + 4*i: 6 + 4*i]) for i in range(n)]

    def minimum_cost(target, a, p, b, q):
        best = 10**30
        # If S is no more expensive per unit of capacity, an optimum
        # uses fewer than a T-machines (otherwise replace a T's by b S's).
        if p * b <= q * a:
            for t in range(a):
                remaining = target - b * t
                s = 0 if remaining <= 0 else (remaining + a - 1) // a
                best = min(best, t * q + s * p)
        else:
            # Symmetric argument: use fewer than b S-machines.
            for s in range(b):
                remaining = target - a * s
                t = 0 if remaining <= 0 else (remaining + b - 1) // b
                best = min(best, s * p + t * q)
        return best

