class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        length = len(s)

        # Binomial coefficients are used to count completions of a prefix.
        comb = [[0] * (length + 1) for _ in range(length + 1)]
        for i in range(length + 1):
            comb[i][0] = comb[i][i] = 1
            for j in range(1, i):
                comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % MOD

        # If a number has j set bits, it is reducible exactly when j reaches
        # 1 in at most k-1 further operations.
        eligible = [False] * (length + 1)
        for j in range(1, length + 1):
            value = j
            steps = 0
            while value != 1:
                value = value.bit_count()
                steps += 1
            eligible[j] = steps <= k - 1

        answer = 0
        prefix_ones = 0
        for pos, bit in enumerate(s):
            if bit == '1':
                remaining = length - pos - 1
                # Make this bit zero; the resulting number is then less than s.
                for total_ones in range(1, length + 1):
                    need = total_ones - prefix_ones
                    if eligible[total_ones] and 0 <= need <= remaining:
                        answer = (answer + comb[remaining][need]) % MOD
                prefix_ones += 1

        return answer

