import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    adj = [0] * n
    p = 2
    for _ in range(m):
        u, v = data[p] - 1, data[p + 1] - 1
        p += 2
        adj[u] |= 1 << v
        adj[v] |= 1 << u

    rows = adj[:]
    pivots = []
    rank = 0
    for col in range(n):
        selected = None
        for i in range(rank, n):
            if (rows[i] >> col) & 1:
                selected = i
                break
        if selected is None:
            continue
        rows[rank], rows[selected] = rows[selected], rows[rank]
        for i in range(n):
            if i != rank and ((rows[i] >> col) & 1):
                rows[i] ^= rows[rank]
        pivots.append(col)
        rank += 1

    pivot_set = set(pivots)
    free = [c for c in range(n) if c not in pivot_set]
    dimension = len(free)
    values = [0] * n

    # The shift is immaterial mathematically; keeping it also matches the
    # conventional sample construction, while respecting the 60-bit limit.
    shift = 2 if m and dimension <= 58 else 0
    for b, f in enumerate(free):
        bit = 1 << (b + shift)
        values[f] |= bit
        for i, c in enumerate(pivots):
            if (rows[i] >> f) & 1:
                values[c] |= bit

    if any(x == 0 for x in values):
        print("No")
    else:
        print("Yes")
        print(*values)

if __name__ == "__main__":
    main()

