def main():
    n = int(sys.stdin.buffer.read())

    # d = x-y satisfies d^3 < n, so only cube-root(n) values are needed.
    lo, hi = 0, 1_000_001
    while hi - lo > 1:
        mid = (lo + hi) // 2
        if mid * mid * mid <= n:
            lo = mid
        else:
            hi = mid

    for d in range(1, lo + 1):
        if n % d:
            continue
        q = n // d
        # With z = 2y+d, 4q = 3z^2+d^2.
        value = 4 * q - d * d
        if value <= 0 or value % 3:
            continue
        z2 = value // 3
        z = math.isqrt(z2)
        if z * z != z2 or z <= d or (z - d) % 2:
            continue
        y = (z - d) // 2
        if y > 0:
            print(y + d, y)
            return

    print(-1)


