class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        half = (n + 1) // 2

        powers = [1] * n
        for i in range(1, n):
            powers[i] = powers[i - 1] * 10 % k

        coeff = [0] * half
        for i in range(half):
            mirror = n - 1 - i
            coeff[i] = (powers[i] + (powers[mirror] if mirror != i else 0)) % k

        # possible[i][r] says that positions i onward can contribute
        # residue r modulo k.
        possible = [bytearray(k) for _ in range(half + 1)]
        possible[half][0] = 1
        for i in range(half - 1, -1, -1):
            row = possible[i]
            nxt = possible[i + 1]
            c = coeff[i]
            for residue in range(k):
                if nxt[residue]:
                    for digit in range(10):
                        row[(residue + digit * c) % k] = 1

        left = []
        residue = 0
        for i in range(half):
            digits = range(9, 0, -1) if i == 0 else range(9, -1, -1)
            c = coeff[i]
            for digit in digits:
                required = (-residue - digit * c) % k
                if possible[i + 1][required]:
                    left.append(str(digit))
                    residue = (residue + digit * c) % k
                    break

        prefix = ''.join(left)
        return prefix + prefix[:n // 2][::-1]

