class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        pref = [0] * (n + 1)
        for i, x in enumerate(nums):
            pref[i + 1] = pref[i] + x

        # nxt[i] is the first position to the right with a strictly larger value.
        nxt = [n] * n
        stack = []
        for i in range(n - 1, -1, -1):
            while stack and nums[stack[-1]] <= nums[i]:
                stack.pop()
            if stack:
                nxt[i] = stack[-1]
            stack.append(i)

        # A chain of nxt links describes the successive prefix maxima.
        # Binary lifting stores the cost of traversing complete chain blocks.
        levels = n.bit_length()
        up = [array('i', nxt)]
        first_cost = (
            (nums[i] * (nxt[i] - i) - (pref[nxt[i]] - pref[i]))
            if nxt[i] < n else 0
            for i in range(n)
        )
        costs = [array('q', first_cost)]

        for _ in range(1, levels):
            prev_up = up[-1]
            prev_cost = costs[-1]
            cur_up = array('i', [n]) * n
            cur_cost = array('q', [0]) * n
            for i in range(n):
                mid = prev_up[i]
                if mid < n:
                    cur_up[i] = prev_up[mid]
                    cur_cost[i] = prev_cost[i] + prev_cost[mid]
            up.append(cur_up)
            costs.append(cur_cost)

        def make_cost(left, right):
            pos = left
            result = 0
            for level in range(levels - 1, -1, -1):
                nxt_pos = up[level][pos]
                if nxt_pos <= right:
                    result += costs[level][pos]
                    pos = nxt_pos
            result += nums[pos] * (right - pos + 1) - (pref[right + 1] - pref[pos])
            return result

        answer = 0
        for left in range(n):
            lo, hi = left, n
            while lo < hi:
                mid = (lo + hi) // 2
                if make_cost(left, mid) <= k:
                    lo = mid + 1
                else:
                    hi = mid
            answer += lo - left
        return answer

