import sys
from functools import lru_cache

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    N, M, L = data[:3]
    values = data[3:]
    K = N + M + L

    takahashi = (1 << N) - 1
    aoki = ((1 << M) - 1) << N
    all_cards = (1 << K) - 1

    lower = [0] * K
    for i in range(K):
        mask = 0
        for j in range(K):
            if values[j] < values[i]:
                mask |= 1 << j
        lower[i] = mask

    sys.setrecursionlimit(1000000)

    @lru_cache(maxsize=None)
    def winning(tmask, amask, turn):
        hand = tmask if turn == 0 else amask
        if hand == 0:
            return False

        table = all_cards ^ (tmask | amask)
        choices = hand
        while choices:
            played = choices & -choices
            choices -= played
            x = played.bit_length() - 1

            nt = tmask ^ played if turn == 0 else tmask
            na = amask ^ played if turn == 1 else amask

            # Put the card on the table without taking another card.
            if not winning(nt, na, 1 - turn):
                return True

            # Take any strictly smaller card from the table.
            takeable = table & lower[x]
            while takeable:
                taken = takeable & -takeable
                takeable -= taken
                if turn == 0:
                    if not winning(nt | taken, na, 1):
                        return True
                else:
                    if not winning(nt, na | taken, 0):
                        return True

        return False

    print("Takahashi" if winning(takahashi, aoki, 0) else "Aoki")

