class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        n = len(s)
        a, b, c = p.split('*')

        def occurrences(t):
            m = len(t)
            if m == 0:
                return bytearray(b'\1' * (n + 1))

            pi = [0] * m
            j = 0
            for i in range(1, m):
                while j and t[i] != t[j]:
                    j = pi[j - 1]
                if t[i] == t[j]:
                    j += 1
                pi[i] = j

            result = bytearray(n + 1)
            j = 0
            for i, ch in enumerate(s):
                while j and ch != t[j]:
                    j = pi[j - 1]
                if ch == t[j]:
                    j += 1
                if j == m:
                    result[i - m + 1] = 1
                    j = pi[j - 1]
            return result

        def next_occurrence(has):
            result = [n] * (n + 2)
            nxt = n
            for i in range(n, -1, -1):
                if has[i]:
                    nxt = i
                result[i] = nxt
            return result

        has_a = occurrences(a)
        has_b = occurrences(b)
        has_c = occurrences(c)
        next_b = next_occurrence(has_b)
        next_c = next_occurrence(has_c)
        la, lb, lc = len(a), len(b), len(c)

        best = n + 1
        for start in range(n + 1):
            if not has_a[start]:
                continue
            after_a = start + la
            if after_a > n:
                continue

            start_b = next_b[after_a]
            if start_b == n and not (lb == 0 and has_b[n]):
                continue
            start_c = next_c[start_b + lb]
            if start_c == n and not (lc == 0 and has_c[n]):
                continue

            best = min(best, start_c + lc - start)

        return -1 if best == n + 1 else best

