import sys
from itertools import combinations

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, k = data[0], data[1]
    a = data[2:]

    total = 0
    for v in a:
        total ^= v

    # Enumerate the smaller side of the selection.  If we enumerate
    # omitted elements, XOR of the selected elements is total XOR omitted.
    r = min(k, n - k)
    if r == 0:
        print(total)
        return

    answer = 0
    if k <= n - k:
        for comb in combinations(a, k):
            value = 0
            for v in comb:
                value ^= v
            if value > answer:
                answer = value
    else:
        for comb in combinations(a, n - k):
            omitted = 0
            for v in comb:
                omitted ^= v
            value = total ^ omitted
            if value > answer:
                answer = value

    print(answer)

if __name__ == '__main__':
    main()

