import sys

def main():
    z = sys.stdin.buffer.read().split()
    if not z: return
    K = int(z[0]); s = z[1].decode(); t = z[2].decode()
    n, m = len(s), len(t)
    if abs(n-m) > K:
        print('No'); return
    # Double rolling hashes, used only to skip long equal runs.
    B = 911382323
    M1, M2 = 1000000007, 1000000009
    def make(a, mod):
        h=[0]*(len(a)+1); p=[1]*(len(a)+1)
        for i,c in enumerate(a):
            h[i+1]=(h[i]*B+ord(c)+1)%mod
            p[i+1]=p[i]*B%mod
        return h,p
    a1,p1=make(s,M1); a2,p2=make(s,M2)
    b1,q1=make(t,M1); b2,q2=make(t,M2)
    def equal(i,j,l):
        return ((a1[i+l]-a1[i]*p1[l])%M1 == (b1[j+l]-b1[j]*q1[l])%M1 and
                (a2[i+l]-a2[i]*p2[l])%M2 == (b2[j+l]-b2[j]*q2[l])%M2)
    def extend(i,j):
        lim=min(n-i,m-j); lo=0; hi=lim
        while lo<hi:
            mid=(lo+hi+1)//2
            if equal(i,j,mid): lo=mid
            else: hi=mid-1
        return i+lo
    v={0:extend(0,0)}
    if v[0]>=n and v[0]==m:
        print('Yes'); return
    for e in range(1,K+1):
        w={}
        for d in range(-e,e+1):
            x=-1
            if d-1 in v: x=max(x,v[d-1])
            if d in v: x=max(x,v[d]+1)
            if d+1 in v: x=max(x,v[d+1]+1)
            if x<0: continue
            j=x-d
            if 0<=j<=m:
                x=extend(x,j); w[d]=x
                if x>=n and x-d>=m:
                    print('Yes'); return
        v=w
    print('No')
