from typing import List

class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for i in range(1, n):
            children[parent[i]].append(i)

        post = []
        stack = [(0, 0)]
        while stack:
            x, state = stack.pop()
            if state == 0:
                stack.append((x, 1))
                for y in reversed(children[x]):
                    stack.append((y, 0))
            else:
                post.append(x)

        pos = [0] * n
        size = [1] * n
        for k, x in enumerate(post):
            pos[x] = k
            if parent[x] != -1:
                size[parent[x]] += size[x]

        transformed = [-1] * (2 * n + 1)
        for k, x in enumerate(post):
            transformed[2 * k + 1] = ord(s[x])

        radius = [0] * len(transformed)
        center = right = 0
        for i in range(len(transformed)):
            if i < right:
                radius[i] = min(right - i, radius[2 * center - i])
            while (i - radius[i] - 1 >= 0 and
                   i + radius[i] + 1 < len(transformed) and
                   transformed[i - radius[i] - 1] == transformed[i + radius[i] + 1]):
                radius[i] += 1
            if i + radius[i] > right:
                center, right = i, i + radius[i]

        answer = [False] * n
        for x in range(n):
            start = pos[x] - size[x] + 1
            answer[x] = radius[2 * start + size[x]] >= size[x]
        return answer

