class Solution:
    def maxSubarraySum(self, nums: List[int], k: int) -> int:
        # Prefix sums at positions with the same remainder modulo k
        # delimit subarrays whose lengths are divisible by k.
        minimum = [None] * k
        minimum[0] = 0
        prefix = 0
        best = None

        for position, value in enumerate(nums, 1):
            prefix += value
            remainder = position % k
            old = minimum[remainder]
            if old is not None:
                candidate = prefix - old
                if best is None or candidate > best:
                    best = candidate
            if old is None or prefix < old:
                minimum[remainder] = prefix

