import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        digits = len(str(n))
        upper = 10 ** digits
        lower = 1 if digits == 1 else 10 ** (digits - 1)

        prime = [True] * upper
        prime[0] = False
        if upper > 1:
            prime[1] = False
        for p in range(2, int(upper ** 0.5) + 1):
            if prime[p]:
                prime[p * p:upper:p] = [False] * (((upper - 1 - p * p) // p) + 1)

        if prime[n] or prime[m]:
            return -1

        inf = 10 ** 30
        dist = [inf] * upper
        dist[n] = n
        heap = [(n, n)]
        powers = [10 ** i for i in range(digits)]

        while heap:
            cost, value = heapq.heappop(heap)
            if cost != dist[value]:
                continue
            if value == m:
                return cost

            for power in powers:
                digit = (value // power) % 10

                if digit < 9:
                    nxt = value + power
                    if not prime[nxt] and cost + nxt < dist[nxt]:
                        dist[nxt] = cost + nxt
                        heapq.heappush(heap, (dist[nxt], nxt))

                # Do not create a leading zero, which would change the digit count.
                if digit > 0 and not (power == powers[-1] and digit == 1):
                    nxt = value - power
                    if nxt >= lower and not prime[nxt] and cost + nxt < dist[nxt]:
                        dist[nxt] = cost + nxt
                        heapq.heappush(heap, (dist[nxt], nxt))

        return -1

