from typing import List

class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        n = len(source)
        m = len(pattern)
        is_target = [False] * n
        for index in targetIndices:
            is_target[index] = True

        inf = n + 1
        # dp[j] is the minimum number of target characters used to
        # form pattern[:j] from the source prefix processed so far.
        dp = [inf] * (m + 1)
        dp[0] = 0
        for i, char in enumerate(source):
            cost = 1 if is_target[i] else 0
            for j in range(m - 1, -1, -1):
                if char == pattern[j] and dp[j] != inf:
                    candidate = dp[j] + cost
                    if candidate < dp[j + 1]:
                        dp[j + 1] = candidate

        # Keep the cheapest embedding of pattern; every other target
        # position can be removed.
        return len(targetIndices) - dp[m]

