class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        # Traversing edges backwards from 0 finds all nodes that can reach 0.
        reverse = [[] for _ in range(n)]
        weights = set()
        for a, b, w in edges:
            reverse[b].append((a, w))
            weights.add(w)

        values = sorted(weights)

        def reachable(limit: int) -> bool:
            seen = [False] * n
            seen[0] = True
            queue = deque([0])
            count = 1
            while queue:
                v = queue.popleft()
                for u, w in reverse[v]:
                    if w <= limit and not seen[u]:
                        seen[u] = True
                        count += 1
                        queue.append(u)
            return count == n

        if not values or not reachable(values[-1]):
            return -1

        lo, hi = 0, len(values) - 1
        while lo < hi:
            mid = (lo + hi) // 2
            if reachable(values[mid]):
                hi = mid
            else:
                lo = mid + 1
        return values[lo]

