class Solution:
    def calculateScore(self, s: str) -> int:
        # For each letter, retain unmatched indices as a stack.  The latest
        # unmatched index is the closest eligible one.
        waiting = [[] for _ in range(26)]
        score = 0
        for i, ch in enumerate(s):
            letter = ord(ch) - ord('a')
            mirror = 25 - letter
            if waiting[mirror]:
                score += i - waiting[mirror].pop()
            else:
                waiting[letter].append(i)
        return score

